    // Catch-all to_ptr: accepts a Julia proxy carrying a ptr field.
    template<typename M> bool to_ptr(jl_value_t *p, M** m) {
      if (is_null(p)) return false;
      void* raw = 0;
      if (!SWIG_IsOK(SWIG_ConvertPtr(p, &raw, 0, 0))) return false;
      if (m) *m = static_cast<M*>(raw);
      return true;
    }


    // Check if conversion is possible
    template<typename M> bool can_convert(jl_value_t *p) { return to_ptr(p, static_cast<M**>(0));}

