    // Specialization for std::vectors of booleans
    jl_value_t* from_ref(std::vector<bool>::const_reference m) {
      bool tmp = m;
      return from_ptr(&tmp);
    }

    // Same as the above, but with a temporary object
    template<typename M> jl_value_t* from_tmp(M m) { return from_ptr(&m);}








